// Read the ROW, not the envelope. The KPI endpoint returns {view, rows, count},
// so healthItems[0].json.checks_failed was always undefined and every threshold
// read that as zero - no check in this node could ever fire.
const healthResp = $('Query Health KPIs').first().json;
const autoResp = $('Query Automation KPIs').first().json;

const MAX_AGE_DAYS = 3;
const WEEK_GRACE_DAYS = 7;
const now = Date.now();
const alerts = [];

// Date.parse is far too permissive for a database date: V8 normalises 2026-02-30
// into March 2 and accepts locale-dependent forms, so a corrupt value can read as
// a fresh one. Require an explicit calendar date and prove it round-trips.
function parseDay(v) {
  if (typeof v !== 'string') return null;
  const m = v.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T ].*)?$/);
  if (!m) return null;
  const y = +m[1], mo = +m[2], d = +m[3];
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) {
    return null;
  }
  return dt.getTime();
}

// A metric we cannot read is NOT a zero. (v || 0) turned missing, null, "" and
// "unknown" all into a passing zero, so a row reading checks_passed 0 of 254 with
// checks_failed absent reported perfect health.
function num(row, key) {
  const v = row[key];
  return (typeof v === 'number' && Number.isFinite(v) && v >= 0) ? v : null;
}

// rows[0] is only the newest if the endpoint sorts that way, and that is not
// contractually guaranteed - it measures newest-first today, which is exactly the
// kind of assumption that already went wrong once in this practice. Pick the max
// proven date, and if any row is undated we cannot prove which is newest, so fail
// closed rather than guess.
function newest(rows, field) {
  let best = null, bestT = -Infinity, undated = 0;
  for (const r of rows) {
    if (!r || typeof r !== 'object') { undated++; continue; }
    const t = parseDay(r[field]);
    if (t === null) { undated++; continue; }
    if (t > bestT) { bestT = t; best = r; }
  }
  return {row: best, t: bestT, undated: undated};
}

function rowsOf(resp) {
  if (!resp || typeof resp !== 'object') return null;
  return Array.isArray(resp.rows) ? resp.rows : null;
}

function check(resp, view, dateField, graceDays, metrics) {
  const rows = rowsOf(resp);
  if (rows === null) {
    alerts.push({severity: 'high', type: 'input_unreadable',
                 msg: view + ' did not return a rows array'});
    return;
  }
  if (rows.length === 0) {
    alerts.push({severity: 'high', type: 'input_empty',
                 msg: view + ' returned no rows in the queried window'});
    return;
  }
  const sel = newest(rows, dateField);
  if (sel.undated > 0) {
    alerts.push({severity: 'high', type: 'input_undated',
                 msg: sel.undated + ' of ' + rows.length + ' ' + view +
                      ' row(s) carry no valid ' + dateField +
                      ', so the newest cannot be identified'});
    return;
  }
  const ageDays = (now - sel.t) / 86400000;
  // A negative age is a clock or data fault, not freshness. Without this a corrupt
  // future date sails past the staleness test as the freshest row available.
  if (ageDays < -1) {
    alerts.push({severity: 'high', type: 'input_future_dated',
                 msg: view + ' newest ' + dateField + ' is ' + Math.round(-ageDays) +
                      ' days in the FUTURE, so its clock or data is wrong'});
    return;
  }
  if (ageDays > graceDays) {
    alerts.push({severity: 'high', type: 'input_stale',
                 msg: view + ' newest row is ' + Math.round(ageDays) + ' days old'});
  }
  for (const m of metrics) {
    const v = num(sel.row, m.key);
    if (v === null) {
      alerts.push({severity: 'high', type: 'input_unreadable',
                   msg: view + '.' + m.key + ' is missing or not a number, so it ' +
                        'cannot be compared against its threshold'});
      continue;
    }
    if (v > m.threshold) {
      alerts.push({severity: m.severity, type: m.key,
                   msg: v + ' ' + m.label + ' (threshold ' + m.threshold +
                        ') as of ' + sel.row[dateField]});
    }
  }
}

check(healthResp, 'kpi_health', 'day', MAX_AGE_DAYS, [
  {key: 'checks_failed', threshold: 0, severity: 'high',     label: 'health checks failed'},
  {key: 'crashes',       threshold: 0, severity: 'critical', label: 'service crashes'}
]);

// The column is heartbeats_failed. The old code read failed_heartbeats, which does
// not exist, so agent failures were structurally invisible.
check(autoResp, 'kpi_automation', 'week', MAX_AGE_DAYS + WEEK_GRACE_DAYS, [
  {key: 'heartbeats_failed',  threshold: 3, severity: 'medium', label: 'agent heartbeats failed'},
  {key: 'heartbeats_timeout', threshold: 3, severity: 'medium', label: 'agent heartbeats timed out'}
]);

return [{json: {
  alerts: alerts,
  alert_count: alerts.length,
  checked_at: new Date().toISOString()
}}];

const items = $input.all();
const outputItems = items.map(i => {
  const j = {...i.json};
  // Redact anything that looks like a secret
  for (const k of Object.keys(j)) {
    if (/token|key|secret|password|auth|bearer/i.test(k)) j[k] = '[REDACTED]';
  }
  return j;
});

return [{ json: {
  workflow_name: $workflow.name,
  execution_id: String($execution.id),
  status: 'completed',
  items_count: items.length,
  finished_at: new Date().toISOString(),
  service_identity: 'n8n-workflows',
  output_items: outputItems.slice(0, 10),
  metadata: { node_count: $workflow.nodes?.length || 0 }
}}];

